insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 1, 'The OKONO suction is a drum at 24.500000 psia holding a liquid whose vapour pressure is 0.950000 psia at a gravity of 1.040000, and the engine returns a pressure head of 52.308173 ft. What has that first term measured?', '["How far the suction pressure stands above the pressure at which this liquid boils, converted to feet at the gravity of the liquid being pumped.", "The absolute suction pressure converted to feet at the gravity of the liquid, with the vapour pressure applied further down the return as a separate deduction from the available head.", "The suction pressure converted to feet of water and then scaled by the gravity, which is why a heavier liquid at the same drum pressure reads as a taller column of head.", "The vapour pressure converted to feet, which is the head the liquid has to be held above before any of the drum pressure counts towards the suction."]'::jsonb, 0, 'The vapour pressure sits inside the first term rather than beside it. An absolute suction pressure on its own says nothing about what keeps a liquid from flashing.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 2, 'Hand the engine a suction of 6.200000 psia on a liquid whose vapour pressure is 6.200000 psia and the pressure head comes back as 0.000000 ft. What does that row establish about the term?', '["That the conversion out of pressure has a floor at zero, so a term that would otherwise go negative is clamped there before the static column is added to it.", "That the gravity of the liquid has dropped out of the conversion, because the pressure and the vapour pressure are equal and cancel before the gravity is applied.", "That it is a difference, since a suction pressure of 6.200000 psia is not small and the term still has nothing to report.", "That the engine refuses to convert a suction pressure it cannot distinguish from the vapour pressure, and returns zero in place of a figure it declines to give."]'::jsonb, 2, 'The suction pressure there is entirely spent holding the liquid as a liquid, so the term that measures the surplus has no surplus to measure. The return is a real 0.000000 ft rather than a placeholder.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 3, 'The OKONO survey states a source standing 6.000000 ft above the pump and 5.500000 ft of suction friction. How do those two terms reach the available head of 52.808173 ft?', '["52.308173 plus 6.000000 plus 5.500000, since both terms describe head the liquid still carries when it arrives and neither of them has been spent yet.", "52.308173 plus 6.000000 less 5.500000, since a source above the pump arrives with its height in hand and the friction is spent before the liquid reaches the flange.", "52.308173 less 6.000000 plus 5.500000, since the liquid has to be lifted to the pump and the friction figure is a recovery credited back at the flange.", "52.308173 less 6.000000 less 5.500000, since both a height and a line loss are demands on the suction and both work against the available head."]'::jsonb, 1, 'The three parts sum on the row to the engine''s own 52.808173 ft. The static column''s sign is a fact about the layout and the friction subtracts on every suction.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 4, 'Padding the OKONO drum from 14.700000 psia to 60.000000 psia takes the available head from 31.040865 ft to 131.659135 ft while the pressure head goes from 30.540865 ft to 131.159135 ft. Why do the two columns walk together across the sweep?', '["The available head is defined as the pressure head scaled by a factor the drum pressure sets, so the two columns are two readings of one quantity.", "The friction term is recomputed at each drum pressure and happens to move by the same amount as the pressure head, which keeps the difference between the columns fixed.", "The static column rises with the drum pressure because a padded drum carries a taller liquid level, and the friction rises with it by the same feet.", "The static column and the suction friction are held on every row, so padding reaches one of the three parts and leaves the other two where the survey put them."]'::jsonb, 3, 'Every row is the same liquid at the same vapour pressure, gravity, static height and friction. Only the drum pressure moved.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 5, 'Read the 4.400000 psia row twice. Its pressure head is -5.856338 ft and the figure beside it is 19.143662 ft. What would somebody looking only at that second number conclude?', '["A figure it cannot use, since the engine returns the available head as a negative number whenever the pressure head goes below zero.", "An ordinary suction with a respectable head on it, because the static column still leaves the figure positive and nothing in the number is marked.", "An error key in place of the available head, since a suction below the vapour pressure is one of the states this call refuses rather than answers.", "A pass flag set to false beside the available head, which is the field that carries the state of the liquid through to the caller."]'::jsonb, 1, 'The arithmetic is still correct arithmetic and 19.143662 ft is what it gives. The warning is the only thing on the return that says the liquid is already flashing.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 6, 'Read the flashing message closely: "the suction pressure is at or below the vapour pressure: the liquid is already flashing before it reaches the pump". What has it established, precisely?', '["That the suction pressure is at or below the vapour pressure of the liquid, which is a statement about the state the liquid arrives in.", "That this pump will cavitate, which is the verdict the message exists to deliver.", "That the head printed beside it is unsafe to quote.", "That the pressure head has gone below zero, which is the condition the message checks."]'::jsonb, 0, 'It is not a cavitation verdict, because this call has never been told the pump''s required NPSH. The 6.200000 psia row carries the warning at a pressure head of 0.000000 ft.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 7, 'Why is the warned call a warning rather than a refusal?', '["The engine refuses only on inputs it cannot read, and a suction of 4.400000 psia against a vapour pressure of 6.200000 psia is readable, so the pressure head of -5.856338 ft is returned as a diagnostic rather than as an answer a caller may quote.", "A refusal would discard the static column, which is still doing useful work here.", "Refusals are reserved for the margin check further down the chain.", "The arithmetic is still correct, so the engine returns the full answer and flags the state of the liquid beside it."]'::jsonb, 3, 'A static column really does add feet of head, and it adds them to a negative pressure head as readily as to a positive one. The available head of 19.143662 ft is the arithmetic, and the warning is the state.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 8, 'The OKONO call returns a warning of null. What is a reader entitled to take from that?', '["That the suction has cleared the pump''s required NPSH, since the warning field is where a failed comparison against required would have been reported.", "That the call ran without an internal error, which is what the field reports, and says nothing at all about the liquid or the drum.", "That the engine found nothing to flag on this suction, which is an answer worth quoting rather than a missing field.", "That the margin rule has been applied to the available head of 52.808173 ft and found it adequate, which is why no comment was attached."]'::jsonb, 2, 'Null there says the engine had nothing to say about the state of the liquid. This call has never seen a required NPSH, so it can report nothing about adequacy.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 9, 'The 5.500000 ft of suction friction is a stated condition rather than a computed one. What follows from that?', '["A guessed friction becomes a guessed NPSH available with nothing on the return to mark the join.", "The friction term is the one part of the three that can be changed without moving steel, which is why the sweep in this module holds it fixed.", "The available head carries a tolerance that widens with the friction figure, and the engine reports that tolerance alongside the 52.808173 ft.", "The engine treats it as an upper bound and reports the worst case."]'::jsonb, 0, 'What a suction line''s length, bore, fittings and rate cost in feet of head belongs to the course that owns line losses. This package takes 5.500000 ft as a number.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 10, 'Which of these does the OKONO available head of 52.808173 ft depend on?', '["The five suction conditions together with the pump''s required NPSH, which is what turns a survey into an available head in the first place.", "The drum pressure, the vapour pressure, the gravity, the static height and the suction friction, and nothing that belongs to the machine.", "The drum pressure and the vapour pressure alone, since the gravity only affects the conversion of the answer into a pressure further down the chain.", "The five suction conditions and the duty flow, since the friction of 5.500000 ft was quoted at the flow the pump is running at."]'::jsonb, 1, 'Nothing in the figure is a property of the machine. The required NPSH is a vendor figure this package does not compute.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 11, 'What can a bare available head support without a required NPSH beside it?', '["A verdict on whether the pump is safe, since a suction that assembles cleanly from its three parts has already cleared the only test this package applies.", "Nothing whatever, since a figure with no vendor number beside it is an intermediate quantity and the engine returns it only so the margin check can read it.", "A comparison between two suctions on one installation, such as padding from 14.700000 psia to 24.500000 psia buying 31.040865 ft against 52.808173 ft.", "A statement about the flow the pump will run at, since the available head and the duty flow move together on a friction-dominated suction."]'::jsonb, 2, 'Every sentence of the form safe, cavitating or adequate has a required NPSH inside it. A comparison between two rows of one sweep has none.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 12, 'The Suction and Changes tab builds the available head from the survey rather than from a single number typed into a box. What does that buy?', '["A figure the engine can check against its own margin rule, which it cannot do for a head that arrived as one number from a caller.", "A figure carrying the warning field, which an available head typed straight in would arrive without.", "A figure with the vendor''s required NPSH already inside it, since the survey is where the vendor figure is entered.", "A figure somebody can argue with, because the drum pressure, the static column and the friction are each visible and each movable."]'::jsonb, 3, 'A suction that reads 52.808173 ft because a drum sits at 24.500000 psia and a source stands 6.000000 ft up can be argued with. One that reads 52.808173 ft because somebody wrote 52.808173 cannot.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 13, 'A sweep of the drum pressure is run and the gravity is quietly changed between rows. What has been produced?', '["A sweep with a wider spread than it should have, which is visible because the pressure head column and the available head column stop walking together.", "A set of different liquids, so the shape the sweep draws is not the shape of padding.", "A sweep the engine rejects, since it holds the liquid fixed across a padding study and refuses a row whose gravity has moved.", "A sweep that is valid for the available head and invalid for the pressure head."]'::jsonb, 1, 'The point of holding the other conditions is that only the drum pressure moved. A row whose liquid changed is a different case rather than a different drum pressure.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 14, 'Of the three parts of NPSH available, why is padding the drum the one usually reached on an installation that is already built?', '["Raising the source, lowering the pump or enlarging the suction line are all steel, and padding is a valve and a gas supply.", "The other two parts are fixed by the survey and the engine will not accept a change to either of them once a case has been stated.", "Padding is the only one of the three that moves the available head, since the static column and the friction cancel each other on most layouts.", "The static column and the friction are computed by this package rather than stated, so a caller has no way to change them."]'::jsonb, 0, 'The parts are not interchangeable as engineering even when they are interchangeable as arithmetic. Padding reaches the pressure head and leaves the other two alone.'),
  ('rotating', 'intermediate', 'module', 'm01-npsh-available', 15, 'A report states that the OKONO suction is fine because it has 52.808173 ft. What is wrong with the sentence?', '["It has quoted a figure that belongs to a drum pressure of 24.500000 psia without stating the pressure, so a reader cannot reproduce it.", "It has quoted the available head where the pressure head of 52.308173 ft is the figure a suction report is written on.", "It has stated a supply and called it a verdict, and nobody can check it because the figure it would be checked against is not in it.", "It has omitted the warning field, which is null on this call and is the only part of the return that carries a verdict."]'::jsonb, 2, 'An available head describes one side of the question. A verdict needs the pump''s required NPSH, and this report has none.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 1, 'Across the whole padding sweep judged against a vendor''s required NPSH of 16.000000 ft, the required margin column reads 5.600000 ft on every row. Why does it never move?', '["The required margin is recomputed from the available head on each row and settles at 5.600000 ft because every row on this sweep came back adequate.", "The required margin is a function of the required NPSH alone, and the required NPSH stayed at 16.000000 ft while only the drum pressure moved.", "The rule holds the required margin fixed once the first row of a sweep has been judged, so later rows are compared against the figure the sweep opened with.", "The required margin tracks the margin itself at a fixed fraction, so a sweep whose margins rise in proportion returns one figure throughout."]'::jsonb, 1, 'The margin of 15.040865 ft at 14.700000 psia and 115.659135 ft at 60.000000 psia both stand against the same 5.600000 ft. Only the required NPSH could move that column.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 2, 'How is the floor of the required-margin rule measured out of the engine rather than read out of the source?', '["Ask at a required NPSH of 16.000000 ft and subtract the fraction''s contribution from the 5.600000 ft returned, which leaves the floor behind.", "Ask with the required NPSH omitted, since the engine falls back on the floor whenever it has no required figure to take a percentage of.", "Ask at the crossover of 8.571428571 ft, where the returned figure is the floor and the fraction at once.", "Ask for a required margin at a required NPSH small enough that the percentage half cannot reach it, and the figure that comes back is the floor of 3.000000000 ft."]'::jsonb, 3, 'At a required NPSH of 4.000000 ft the engine applies 3.000000 ft and the half that bound is the floor. Isolating a maximum means asking where only one of its halves can possibly win.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 3, 'And the fraction?', '["Ask at a required NPSH large enough that the floor cannot reach it and divide the required margin returned by that required NPSH, which gives 0.350000000.", "Divide the floor of 3.000000000 ft by the crossover of 8.571428571 ft, which is the only route to it that does not need a second call.", "Take the boundary ratio of 1.350000000 and subtract one, since the fraction is what the ratio carries above unity on a governed row.", "Read the required margin of 10.500000 ft at a required NPSH of 30.000000 ft and treat it as the fraction directly."]'::jsonb, 0, 'At 30.000000 ft the engine applies 10.500000 ft, and 10.500000 over 30.000000 is the fraction. The floor cannot reach that figure, so only the fraction can have set it.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 4, 'Two independent routes reach the required NPSH at which the floor and the fraction change places. What are they, and what do they give?', '["Halving the available head until the severity changes, and dividing the floor by the fraction. Both give 8.571428571 ft.", "Reading the boundary ratios of 1.750000000 and 1.350000000 and taking their difference of 0.3999999999999999, which locates the crossover on the sweep.", "Halving the required NPSH until the engine''s answer stops being the floor, and dividing the floor by the fraction. Both give 8.571428571 ft.", "Halving the required margin until the pass flag turns over, and multiplying the floor by the fraction."]'::jsonb, 2, 'The first route is a property of the running engine and the second is a property of the rule. The figure is 8.571428571 ft by bisection and 3.000000000 over 0.350000000 by arithmetic.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 5, 'Why is it worth having both routes rather than either one?', '["The bisection alone would be untrustworthy, since halving a required NPSH cannot land on 8.571428571 ft exactly and has to be rounded to it.", "The arithmetic route alone would be untrustworthy, since the floor and the fraction are themselves read out of the source code.", "Two routes are needed because the crossover moves with the available head, so a single measurement would belong to one row of the sweep.", "Their agreement says the engine implements the rule it appears to implement, which neither route can say on its own."]'::jsonb, 3, 'One route measures behaviour and the other measures the stated rule. A gap between them would say the engine is applying something else.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 6, 'Three of the four rows in the crossover table are governed by the fraction, and the boundary ratio on every one of them is 1.350000000. What does that invite a reader to conclude, wrongly?', '["That the boundary ratio is a constant of the engine, since three independent required NPSHs return it and the fourth returns a rounding of it.", "That this package applies a rule on the ratio of available head to required head, since a reader working only at required NPSHs of that size sees one number every time.", "That the fraction of 0.350000000 and the ratio of 1.350000000 are the same quantity written two ways, so either may be quoted as the rule.", "That the floor of 3.000000000 ft has been superseded, since no row in the table above the crossover reaches it."]'::jsonb, 1, 'The floor row gives a boundary ratio of 1.750000000. The three fraction rows are exactly the evidence that hides the difference.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 7, 'At a required NPSH of 16.000000 ft the boundary ratio is 1.350000000 and at 4.000000 ft it is 1.750000000, a difference of 0.3999999999999999. What is that subtraction for?', '["It measures the width of the band the severity reports as marginal.", "It measures the error the engine carries when it converts a margin rule into the ratio it returns beside the pass flag.", "It measures how far a remembered ratio is from the rule the engine applies once the floor takes over.", "It measures the gap between the required margins of 5.600000 ft and 3.000000 ft, expressed as a ratio so the two can be compared."]'::jsonb, 2, 'A margin rule and a ratio rule agree over the range where the fraction happens to bind, and they part company as soon as the floor takes over.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 8, 'A reader carrying 1.350000000 in their head applies it to a pump whose required NPSH is 4.000000 ft. What have they done?', '["Asked for less margin than the engine does, by a shortfall no arithmetic check will find, because the arithmetic is a correct application of the wrong rule.", "Asked for more margin than the engine does, since below the crossover the fraction rises above the floor and the boundary ratio rises with it.", "Reproduced the engine exactly, since the ratio is a property of the rule rather than of the required NPSH it was measured at.", "Produced a figure the engine would refuse, since a ratio supplied where a required margin belongs fails the check''s finiteness test."]'::jsonb, 0, 'On that pump the floor governs and the boundary available head is 7.000000 ft at a ratio of 1.750000000. A remembered 1.350000000 asks for less.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 9, 'Which of the values this check returns can be a graded answer in this course?', '["The required margin, since both halves of the rule that produces it were measured out of the engine to nine decimal places.", "The pass flag, since a boolean carries no unsourced figure and can be checked from the margin and the required margin alone.", "None of them, because the rule behind the required margin, the pass flag and the severity is customary and unsourced here.", "The severity, since its three labels are the engine''s own words and the messages attached to them are quoted verbatim."]'::jsonb, 2, 'Measuring the two halves is worth doing and does not make the rule sourced. The available head itself is gradeable, because every term in it is arithmetic the engine defines.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 10, 'A margin of -4.000000 ft against a required margin of 4.200000 ft returns which severity, and with what note?', '["\"cavitating\", with the note \"NPSH available is below required: this pump will cavitate at this duty\".", "\"marginal\", with the note \"margin of 2.0 ft is below the customary 4.2 ft: acceptable only with vendor agreement and a stable suction\".", "\"cavitating\", with a null note, since the negative margin is the whole of the message and the engine adds nothing to it.", "An error object, since a negative margin is not a state this check classifies and there is no verdict to give on it."]'::jsonb, 0, 'The pass flag on that row is false. A negative margin means the available head is below the required head that was handed in.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 11, 'A margin of 2.000000 ft against a required margin of 4.200000 ft comes back "marginal" with a pass of false. What has the engine said about that suction?', '["That the available head is below the pump''s own requirement, which is what a pass of false reports whichever label travels with it.", "That the available head clears the pump''s own requirement and falls short of the cover the customary rule asks for on top of it.", "That the available head could not be judged against the rule, so the engine has classified it into the middle of the three labels.", "That the required margin of 4.200000 ft was met and the ratio fell short."]'::jsonb, 1, 'Its note reads "margin of 2.0 ft is below the customary 4.2 ft: acceptable only with vendor agreement and a stable suction". That is a statement about the rule.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 12, 'The third label arrives with a pass of true and a null note on a suction holding 13.000000 ft. Why is that short of a promise that the machine will stay clear of cavitation?', '["It is a full promise about cavitation, since the label is defined as the state in which a machine is safe at its duty.", "It is short of a promise only because the note came back null, which leaves no record of which half of the maximum bound.", "It is short of a promise because the ratio was withheld on that row, and the ratio is the field a reviewer would check.", "It reports that one cover was cleared, and clearing a customary cover is no physical guarantee."]'::jsonb, 3, 'Null is the answer in the note field there. Every severity in this check is an output of a held rule.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 13, 'Two of the three severities come back with a pass of false. What does a caller reading only the boolean lose?', '["The difference between a pump that will cavitate and one that clears its vendor requirement with thinner cover than convention wants.", "The ratio and the required margin, which the engine attaches to the label rather than to the flag and drops when the flag is read alone.", "The required margin of 4.200000 ft, which is the one field the two false cases differ on and the only one a boolean cannot carry.", "Nothing that matters, since both false cases call for the same work: more available head, or a different pump."]'::jsonb, 0, 'One needs more available head or a different pump. The other needs vendor agreement and a look at how steady the suction is.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 14, 'An available head that is not a number and an available head of infinity both return the same thing. What is it?', '["A severity of \"cavitating\" with a pass of false, which is how this check has always reported an input it could not place anywhere on its own scale.", "A null severity beside a null pass flag, with the ratio and the required margin still computed from the required NPSH.", "{ error: \"the margin check needs a finite available NPSH: there is no verdict to give on a suction head that cannot be read\" }", "Two different messages, one naming the value as unreadable and the other naming it as unbounded."]'::jsonb, 2, 'One message covers both because both fail the same test, which is that the available head be finite. The refusal names the input it could not read.'),
  ('rotating', 'intermediate', 'module', 'm02-the-margin-and-the-rule-it-is-judged-against', 15, 'Why does the check refuse rather than classify when it cannot read the available head?', '["An unreadable input is the one case where the engine has no default to fall back on, so refusing is what it does in place of applying one.", "The available head is the whole of what the function judges, so there is no severity to report and no pass flag to set.", "A label invented over an unreadable input would come back looking exactly like a label computed from a real one, carrying a pass flag, a ratio and a note that are each a statement about nothing.", "The required NPSH is still readable, so the check could classify on that alone and declines because a one-sided verdict would be misleading."]'::jsonb, 1, 'Strip the available head out and there is nothing left to compare the rule against. A refusal is a returned object carrying an error key, and it is not a pass of false.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 1, 'The speed-change table prints two columns headed "less the ratio squared" and "less the ratio cubed". What are those columns for?', '["They record the correction the engine applies after scaling, which is what separates the result from a bare proportionality.", "They record how far the ratio sits from the ends of the band the engine will report without comment.", "They subtract the law from the engine''s own answer, which is how a claim of exactness is stated rather than asserted.", "They record the residual left by the solve that found the scaled duty, so a reader can see the crossing converged."]'::jsonb, 2, 'The quotient columns say what happened. The difference columns say how close it is to what the law claims. The laws themselves belong to the ESP course, which this one cites.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 2, 'Across the five speed rows the two difference columns print ten figures, of which eight are zero. What are the other two, and what do they mean?', '["5.551115123125783e-17 and 1.1102230246251565e-16, which are what exactness comes to in double-precision arithmetic.", "5.551115123125783e-17 and 1.1102230246251565e-16, the residual left by scaling a duty.", "0.490000000 and 0.810000000, the head quotients on two rows the law missed.", "0.343000000 and 0.729000000, the power quotients where the cube left a remainder."]'::jsonb, 0, 'The two sit at a speed ratio of 0.700000 on the head leg and 0.900000 on the power leg. A lesson that asserts the laws hold and shows a quotient column is asking to be believed.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 3, 'At a speed ratio of 1.100000 the engine returns 1357.898266 gpm, 505.539232 ft and 243.628747 brake hp, with a power quotient of 1.331000000 and a difference from the ratio cubed of 0. Which figure on that row is the one that gets bought?', '["The 1357.898266 gpm, because a station is bought on the flow it delivers and the rest of the row follows from it.", "The 505.539232 ft, because the head is what the vendor quotes a machine against and the power is derived from it downstream.", "The 1.331000000 power quotient, which survives a change of units.", "The 243.628747 brake hp, because the driver has to be able to deliver it."]'::jsonb, 3, 'A flow of 1357.898266 gpm sounds modest beside a base of 1234.452969 gpm. The power went to 1.331000000 of what it was.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 4, 'The warned column is false on all five rows of the speed table. What does that establish?', '["That the engine has endorsed the affinity laws at those five ratios, which is what the column exists to record.", "That the engine declined to interrupt over changes of that size, and nothing more.", "That all five ratios fall inside the band, which is a published correlation limit the engine enforces by refusing outside it.", "That the difference columns came back at or near zero on every row, since the warning is raised off those differences."]'::jsonb, 1, 'A false in that column is the absence of a comment. The band it is measured against is a sanity bound.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 5, 'Both ends of the band the engine reports a speed ratio over without comment were measured rather than read out of a constant. How?', '["By walking the ratio up from 0.010000 and down from 5.000000 until the warning changes state, which gives 0.500000000000 and 1.500000000000.", "By reading the ratios at which the two difference columns stop coming back as zero, which gives 0.500000000000 and 1.500000000000.", "By halving the ratio until the returned brake power leaves the ideal cube, which is the leg the warning names.", "By comparing the scaled duty against a re-solved one until the two part company by more than the engine tolerates."]'::jsonb, 0, 'Each end is the ratio at which the engine''s own behaviour changes. Neither was taken from a declared constant.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 6, 'At a speed ratio of 100.000000 the engine returns 123445.296915 gpm, 4178010.181407 ft and 183041883.582474 brake hp. What has it done with the laws?', '["Refused them, and returned the three figures as a diagnostic rather than as an answer a caller may use.", "Applied them and clamped the power leg, since the cube is the leg the warning names as the dangerous one.", "Applied them, and said out loud that no real machine should be expected to behave this way.", "Applied them and dropped the warning, since a ratio that far out is absurd on its face."]'::jsonb, 2, 'Its warning says "a speed ratio of 100 is far outside the range over which the affinity laws describe a real machine: the power leg goes as the cube, so this is an extrapolation on the number that sizes the driver".'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 7, 'What kind of limit are the two ends of that band?', '["A correlation limit, since the band was measured out of the engine and both ends came back to twelve decimal places.", "A sanity bound, since no publication in this repository says where the affinity laws stop describing a real machine.", "A validity range, since a ratio inside it is certified by the engine and a ratio outside it is refused by it.", "A vendor limit, since it is the same kind of figure as the casing limit the trim warning names."]'::jsonb, 1, 'It is warned on and never used to refuse, and nothing computed from it decides a value. No graded answer in this course sits on it.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 8, 'On the trim table the ideal and the real columns agree on the first three rows and part company from a trim percent of 8.000000 onward. Why?', '["The first three rows sit inside the band the engine reports without comment, and the de-rating begins where that band ends.", "The ideal columns are computed only where the real ones differ, so the first three rows repeat the real figures for readability.", "A trim of five percent or less is within the machining tolerance of a casing, so the engine reports the catalogue duty unchanged.", "The shortfall model is zero at or under five percent of trim, so the first three rows have nothing de-rated on them."]'::jsonb, 3, 'At a trim ratio of 0.950000 the ideal and real flows are both 1172.730321 gpm. At 0.920000 they are 1135.696732 gpm and 1125.475461 gpm.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 9, 'The shortfall model is zero at or under five percent, then 0.006 per further percent, capped at 0.12, applied whole to the head and half to the flow. What does the course do with it?', '["Teaches it and grades it, because the model is stated in full and every figure it produces is reproducible from the engine.", "Teaches it and grades nothing on it, because the engine''s comment calls it \"the published shortfall\" and names no publication.", "Declines to teach it, because a model with no publication behind it cannot be put in front of a reader as engine behaviour.", "Teaches it as the affinity law for a diameter change, which is the form the laws take when the speed is held and the impeller is cut."]'::jsonb, 1, 'No graded value in this course is a trimmed flow, head or shortfall. The speed law beside it is on a different footing and is exact.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 10, 'At a trim ratio of 0.799900 the engine warns about a 20.0 percent trim, and at a trim ratio of 0.800000, a trim percent of 20.000000, the warning is null. What is going on?', '["The 0.800000 row falls inside the shortfall model''s cap of 0.12, and a capped row is reported without a comment.", "The 0.799900 row is a deeper trim than the 0.800000 row by enough to cross the casing limit the message names.", "The engine warns on the trim ratio rather than the trim percent, and a ratio of 0.800000 sits at the bottom of the range the shortfall model covers.", "The threshold is exclusive, so the vendor limit itself does not warn."]'::jsonb, 3, 'The message at 0.799900 reads "a 20.0 percent trim is beyond what most casings tolerate: efficiency falls away and the vendor limit usually sits near 20 percent".'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 11, 'A speed ratio of 0.800000 gives 987.562375 gpm and a trim ratio of 0.800000 gives a real flow of 943.122068 gpm. What separates them?', '["They are different changes to different hardware, and only one of the two is described by a law that holds exactly.", "A trim is a speed change with the shortfall applied twice, once to the head and once to the flow, which is where the difference comes from.", "The trim figure is a re-solved duty and the speed figure is a scaled one, so the two answer different questions about the same change.", "The 987.562375 gpm is the trim''s ideal flow and the 943.122068 gpm its real flow, so both belong to the trim."]'::jsonb, 0, 'The trim''s ideal flow at 0.800000 is also 987.562375 gpm, which is exactly why the two get confused. The real flow is 943.122068 gpm.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 12, 'At a trim ratio of 0.750000 the flow comes out at 0.940000000 of ideal and the head at 0.880000000 of ideal, while the brake power is 1.000000000 of the ideal cube. What does the engine report on that row, and how closely?', '["An implied efficiency ratio of 0.827200000, which a reader has to reach by multiplying the two legs because the field is not on the return.", "An efficiency of 0.827200000, measured on a trimmed impeller and carried through to the brake power on that row.", "An implied efficiency ratio of 0.827200000, against the 0.827200000 the two legs give, a difference of -1.1102230246251565e-16.", "A shortfall percent of 12 and nothing else, since the efficiency the return implies is left for a caller to work out."]'::jsonb, 2, 'The field is the arithmetic the return already contains, stated as a number. A hand division at fewer decimals disagrees with it for no defensible reason.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 13, 'Why is the power leg of a trim left as the ideal cube while the head and flow legs are de-rated?', '["The power leg is the one the affinity laws describe exactly, so it is the only leg of a trim that can be scaled without a correction.", "A cut impeller draws the same power as an uncut one at the same speed.", "The shortfall applies whole to the head and half to the flow, which between them account for the whole of the power and leave nothing for a third leg.", "De-rating it would mean inventing a second unsourced model on top of the first."]'::jsonb, 3, 'The only correction available is the shortfall model, which has no publication in this repository. What the engine owes a reader is the arithmetic it actually did.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 14, 'A trim ratio of 0.950000 is meant to be exactly five percent and the rule says five percent carries no shortfall. The engine returns a trim percent of 5.000000000000004 and a shortfall percent of 0. What has happened?', '["The engine rounded the trim percent back to five before comparing it, which is why the returned figure and the compared figure differ.", "The comparison is carrying a slack, because the subtraction puts the trim percent above five by 4.440892098500626e-15.", "The shortfall is zero because 0.006 per further percent of 4.440892098500626e-15 rounds away, so no slack is needed.", "The rule is written as at or under five percent and 5.000000000000004 is under five once the trailing figures are discarded."]'::jsonb, 1, 'A bare test against five would have put that row on the wrong side and produced a shortfall where the rule says none belongs.'),
  ('rotating', 'intermediate', 'module', 'm03-a-speed-change-and-a-trim', 15, 'How large is that slack, and how was it found?', '["By halving the trim ratio until the shortfall leaves zero: 5.000000000999993 with none and 5.0000000010000045 with one, so the boundary sits 1.0000045236324695e-9 above five percent.", "By reading it off the trim percent of 5.000000000000004, which is the gap the comparison has to span and is 4.440892098500626e-15 wide.", "By walking the trim ratio until the warning changes state, the same route that gave the two ends of the speed band.", "By comparing the shortfall percent of 0.006000000000002004 at a trim ratio of 0.949900 against the 0 at 0.950000."]'::jsonb, 0, 'The rule is written in whole percent and the value it is compared against is not one. The warning boundary carries the same slack, and a trim percent of 19.999999999999996 still returns null.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 1, 'A trim ratio of 0.950000 gives a re-solved duty of 1131.756344 gpm and a one-point answer of 1172.730321 gpm, a flow quotient of 1.036203885. Why is that row the cleanest evidence in the section?', '["Its shortfall percent is 0, so the two answers agree everywhere except on the flow, which is the leg the model reaches first.", "It is the only row where the scaled curve and the system curve cross twice, so the gap is the distance between the two crossings.", "It is the row where the two ratios are closest to one, so the quotient of 1.036203885 is the smallest error the composition can produce.", "Its shortfall percent is 0, so the model that would be the obvious suspect contributed nothing and the gap is still there."]'::jsonb, 3, 'The gap is that the system curve did not move when the machine changed, so the machine meets it somewhere else.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 2, 'Why can an affinity law applied to an old duty point not know where the pump will now run?', '["The laws are stated for a change of speed, so applying them to a trim carries an error that grows with the depth of the cut.", "The laws are a statement about the machine alone, and nothing in them refers to a static head or a friction head.", "The laws scale a curve rather than a point, so applying them to a single coordinate pair loses the shape of the curve around it.", "The laws hold only inside the band the engine reports without comment, and a re-solved duty can land outside it."]'::jsonb, 1, 'A duty point is a property of the machine and the system together, and it exists only because the two curves meet.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 3, 'The Pump Station Designer draws its duty headline one way and shows a second figure in a card headed "What a change would buy". What is that card?', '["A cross-check on the headline, so a reader can see the two routes agree before trusting the duty printed above.", "The duty the station would reach if the system curve were re-rated for the change as well as the machine.", "The affinity map, which says where the machine you had ends up on the machine you now have.", "A sensitivity band around the headline duty, drawn from the ends of the speed ratio band."]'::jsonb, 2, 'The crossing is the operating point. The two are different questions and the studio labels them as two.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 4, 'Asked at a unit duty, a pure speed ratio of 1.100000 returns a flow factor of 1.100000000 and a head factor of 1.210000000, while a pure trim ratio of 0.800000 returns 0.764000000 and 0.582400000. Why do the trim factors not read as a clean ratio and its square?', '["The shortfall model is inside those factors, so a trim of 0.800000 does not scale flow by 0.800000000.", "The trim factors are quoted at the best efficiency point and the speed factors at the duty, so the two are read against different references.", "The trim factors carry the implied efficiency ratio as well, which is why both of them fall below the plain ratio and its square.", "The engine applies the cube to a trim and the square to a speed change, so the head factor of 0.582400000 is a cubed quantity."]'::jsonb, 0, 'A trim ratio of 0.950000 returns a flow factor of 0.950000000, because that is a trim the model leaves alone.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 5, 'What is gained by reading the scaling factors out of the engine rather than restating them in whatever draws the chart?', '["The factors then carry the shortfall model, which a chart drawn from restated affinity laws would have to apply separately.", "The curve and the point are scaled by the same numbers, so they cannot drift apart when the engine moves.", "The engine returns the factors to more decimal places than a restatement would carry, so the chart is drawn more precisely.", "The factors are validated against the published cases on the way out, which a local copy of the laws would not be."]'::jsonb, 1, 'Two implementations of one rule agree until one of them changes. At a trim of 0.800000 a hand-coded factor of 0.800000000 disagrees with the engine''s 0.764000000.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 6, 'The combined row, a speed ratio of 1.100000 with a trim ratio of 0.900000, returns a flow factor of 0.975150000 and a head factor of 0.950697000. What is that row for?', '["It shows that the two changes cancel, since both factors come back close to one.", "It shows the factors at the boundary of the band the engine reports without comment.", "It shows the largest disagreement between the crossing and the affinity map in the section.", "It shows the factors for both changes at once, which is the case a studio has to scale a curve for."]'::jsonb, 3, 'The pure speed rows and the pure trim rows are the other two shapes. Nothing in the table is restated: each figure is what the engine does to a duty of one.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 7, 'At a trim ratio of 0.950000 the one-point answer is 1172.730321 gpm at 377.065419 ft, and the scaled curve read at that flow gives 377.065419 ft, a difference of 0 ft. What does that settle?', '["That the affinity map is a real point on the new machine''s curve rather than an approximation the re-solve corrects.", "That the affinity map and the crossing are the same point once the curve has been scaled, and the quotient of 1.036203885 is a reporting artefact.", "That the scaled curve was built from the one-point answer, so reading it back there cannot disagree.", "That the system curve passes through the one-point answer as well, which is what makes it a duty."]'::jsonb, 0, 'It is a point on the machine you now have. It is simply not where that machine will run.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 8, 'A power figure is wanted after a trim to 0.800000. The re-solved duty is 695.297235 gpm at 275.923397 ft and the one-point answer is 943.122068 gpm at 243.327313 ft. Which should the power be built on?', '["The one-point answer, because it is the point the affinity laws place the machine at and the laws are exact for a scaling.", "Either, because a power figure is a product of flow and head and the two answers bracket the same product.", "The re-solved duty, because that is where the pump will run and everything downstream hangs off it.", "The one-point answer, because the re-solved duty belongs to the system rather than to the machine whose power is wanted."]'::jsonb, 2, 'A power built on a one-point flow is a power for a flow the pump will not deliver, and no unit check will catch it.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 9, 'At a speed ratio of 0.700000 the two answers are 502.692592 gpm at 244.459069 ft and 864.117078 gpm at 204.722499 ft, with quotients of 1.718977148 and 0.837451028. What does the flow quotient measure?', '["The distance between two correct answers to two different questions.", "The error the re-solve corrects, a factor of 1.718977148.", "The share of the change that the system curve absorbed rather than the machine, which rises as the change deepens.", "The two flows the machine makes at one head."]'::jsonb, 0, 'Nothing on that row is wrong by that factor. Both figures are the engine''s and both are right about their own question.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 10, 'At a speed ratio of 1.100000 the flow quotient is 0.949032669 and the head quotient is 1.033460604. How does that sit beside the row at 0.700000, where they are 1.718977148 and 0.837451028?', '["The arrangement is the same, since both rows put the flow quotient above one and the head quotient below it.", "The arrangement is reversed because the row at 1.100000 is outside the band the engine reports without comment.", "The arrangement is reversed, so the direction of the gap is a property of the change rather than of the composition.", "The arrangement is reversed because a speed increase re-solves on the static part of the system curve rather than the friction part."]'::jsonb, 2, 'A machine scaled down meets the fixed system at one flow and a machine scaled up meets it at another. Assuming the two quotients move together is the mistake.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 11, 'Both tables carry a row at a ratio of 1.000000 where every quotient reads 1.000000000. Why?', '["On that row both scaling factors are 1.000000000.", "On that row the base duty of 1234.452969 gpm at 417.801018 ft is the published case, and the published case is where the two methods are reconciled.", "On that row the two curves are tangent.", "On that row the machine was not changed, so the two questions collapse into one."]'::jsonb, 3, 'The two answers agree there because nothing happened. Reading that agreement as evidence the distinction is academic is the third mistake in the lesson.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 12, 'Reading down the trim rows, the flow quotient goes 1.000000000, 1.036203885, 1.099939243, 1.195804570, 1.356430057, 1.688794663. What should a reader take from the shape?', '["The quotient grows without bound as the trim deepens, so below a trim ratio of 0.750000 the two methods carry no relation at all.", "Small changes put the two answers close together and large ones put them far apart, and the interesting proposals are the large ones.", "The quotient grows because the shortfall model grows with the trim, so it is the model rather than the system that opens the gap.", "The quotient grows in proportion to the trim percent, so a reader can interpolate the gap for any trim from two rows."]'::jsonb, 1, 'A reader who checks the two methods at a trim ratio of 0.950000 and decides 1.036203885 does not matter will carry that to 0.750000, where it is 1.688794663.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 13, 'At a trim ratio of 0.750000 the flow quotient is 1.688794663 and the head quotient is 0.839967688. What does that pair rule out?', '["That the head quotient can ever exceed one, since a trimmed machine makes less head than it did.", "That the re-solved head can exceed the one-point head, since 246.213642 ft and 206.811504 ft show the opposite.", "That the two quotients move together, which the speed row at 1.100000 rules out again in the other direction.", "That the shortfall model is inside the re-solve, since a model applied to both answers would cancel from the quotients."]'::jsonb, 2, 'At a speed ratio of 1.100000 the pair is 0.949032669 and 1.033460604, which is the opposite arrangement.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 14, 'What makes the crossing and the affinity map different paths rather than two estimates of one path?', '["The new crossing slides along a system curve that never moved, and the map slides along the machine''s own law.", "The crossing is solved and the map is scaled, so the crossing carries a residual the map does not and the two differ by it.", "The map uses a trim''s ideal columns and the crossing its real ones.", "The crossing is taken at the best efficiency flow and the map at the old duty flow, so the two start from different points."]'::jsonb, 0, 'The two paths start at the same point, at a ratio of 1.000000, and they are different paths, so the further a change goes the further apart they land.'),
  ('rotating', 'intermediate', 'module', 'm04-an-affinity-law-is-not-a-duty-point', 15, 'A report gives the duty after a speed change to 0.800000 as 987.562375 gpm. What has it reported?', '["The re-solved duty, the figure a headline carries.", "A point on the new curve, when the pump will run at 791.589335 gpm.", "The ideal flow of a trim to 0.800000.", "A flow the engine never returns at 0.800000."]'::jsonb, 1, 'The re-solved answer on that row is 791.589335 gpm at 295.447319 ft, and the one-point answer is 987.562375 gpm at 267.392652 ft.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 1, 'How does the engine build the duty for machines in parallel?', '["It adds heads at equal flow to make a new machine curve, then solves the crossing of that curve with the system that was already there.", "It adds flows at equal head to make a new machine curve, then solves the crossing of that curve with the system that was already there.", "It solves one machine''s duty and multiplies the flow by the machine count, which is exact because the machines are identical.", "It re-rates the system curve for the extra machines and reads the original curve against it at the new friction head."]'::jsonb, 1, 'Machines in parallel share a suction and a discharge, so they all work against the same head. The duty is then solved the way any duty is solved.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 2, 'On a system of 60.000000 ft static plus 380.000000 ft of friction at 1100.000000 gpm, one machine gives 1103.518695 gpm and two give 1198.970966 gpm. What is the flow over one machine on that second row?', '["Two exactly, since the machines are identical and parallel operation adds their flows.", "1.661125814, which is what the second machine buys on this system.", "1.086498100, and the second machine is carrying far less than the first.", "1.105087375, which is the figure for two machines on a friction-dominated system."]'::jsonb, 2, '1.661125814 is the head over one machine for two in series, and 1.105087375 is the flow over one machine for three in parallel.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 3, 'Why does the second machine buy so little?', '["Each machine runs further left on its own curve and the system demands more head for the extra flow.", "The two machines interfere on a shared suction, so each of them makes less head than it would alone.", "The combined curve is flatter than one machine''s curve, so it crosses the same system at a lower head.", "The second machine is running outside the range either side of best efficiency flow, where it makes less flow per unit of head."]'::jsonb, 0, 'One machine carries 1103.518695 gpm alone, and with a second on the manifold each carries 599.485483 gpm. The duty head rises from 442.434987 ft to 511.456135 ft.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 4, 'The four-machine row reads 1226.902650 gpm at 532.735738 ft, with 306.725662 gpm per machine. What has a reader been shown?', '["A station that has reached the limit of what parallel operation can deliver on any system, whatever the shape of that system''s own curve.", "A station whose per-machine flow has fallen below the figure at which the engine warns.", "A station whose duty head has stopped rising, which is the signal that a fifth machine would buy nothing.", "A station whose flow is still climbing and whose machines are each carrying less than a third of what one carried alone."]'::jsonb, 3, 'The station flow on that row is 1226.902650 gpm against 1103.518695 gpm for one machine. Everything about whether the fourth is worth buying sits outside this calculation.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 5, 'Is the shortfall from doubling a property of the pumps?', '["Yes. Identical machines on one manifold share a discharge and each loses head to the other.", "Yes. The combined curve is fitted from the single curve, so it carries the fit''s own error twice over.", "No. A system whose head is mostly friction rises steeply with flow, so extra flow is expensive in head.", "No. The shortfall comes from the engine re-solving rather than doubling, which is a difference in method rather than in the machines."]'::jsonb, 2, 'A system whose head is mostly static behaves differently. The way to find out is to state the system and re-solve.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 6, 'Three machines in series on the same system give 1676.470978 gpm at 942.653617 ft, with a head over one machine of 2.130603693. Why is that figure below three?', '["The duty flow moved from 1103.518695 gpm to 1676.470978 gpm, and a taller curve crosses the same system further to the right.", "The heads of machines in series add with a loss at each stage, which is what the figure below three records.", "The third machine is running further left on its own curve, so it contributes less head than the first two.", "The engine re-solves a series stack at the flow of a single machine, so the figure is a ratio of two different duties."]'::jsonb, 0, 'At the duty the heads do not appear to add, and the reason is that the duty flow is not fixed. The crossing moved.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 7, 'At a flow of 1000.000000 gpm one machine makes 459.953894 ft and three in series make 1379.861681 ft, a quotient of 3.000000000. What does that test separate?', '["A stack built from a drooping curve, which reads back exactly, from one built from a curve that does not droop.", "The engine''s series combination from its parallel one, since only the series route is exact at a stated flow.", "The published curve fit from the system curve, since only one of the two is evaluated at a flow the caller names.", "Adding heads at a fixed flow, which is exact, from the duty head of a stack, where the crossing has moved."]'::jsonb, 3, 'The combination is not an approximation. Three times 442.434987 ft is not the duty head of 942.653617 ft, and the difference is the duty flow moving.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 8, 'What comes back from a request for parallel operation on two and a half machines?', '["{ error: \"series operation needs a pump curve and a whole number of machines, at least one\" }", "{ error: \"parallel operation needs a pump curve and a whole number of machines, at least one\" }", "A combined curve for two machines, since the engine rounds a machine count down to the nearest whole number.", "A combined curve interpolated between the two-machine and three-machine cases."]'::jsonb, 1, 'Each message names its own operation and states both halves of what it needs: a pump curve, and a count that is whole and at least one.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 9, 'Why is a fractional machine count refused rather than rounded?', '["Rounding would break the parallel combination, which adds flows at equal head and needs an exact count to do so.", "The engine has no default machine count to fall back on, and refusing is what it does wherever a default is missing.", "A count of two and a half would put the combined curve outside the range the duty solve searches over.", "A curve returned for it would be an answer to a question nobody can ask, and the reader would not know which count it belonged to."]'::jsonb, 3, 'There is no machine that is half a pump and no manifold that holds two and a half of them. Refusing puts the problem back in the input.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 10, 'A stack of four machines is built from a curve that does not fall with flow. What does the duty solve return?', '["{ error: \"parallel operation needs a pump curve and a whole number of machines, at least one\" }", "{ error: \"this curve does not fall with flow, so it is not a centrifugal head curve and its crossing with a system curve is not a duty point: check the catalogue points\" }", "A duty point, since combining four machines restores the droop the single curve was missing.", "A duty point with the droop flag set to false, so a caller can decide whether to use it."]'::jsonb, 1, 'Combinations carry the properties of the curve they were built from. The message names where to look, which is the catalogue points the curve was fitted from.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 11, 'What is B in the Hydraulic Institute correction, and where is the correction applied?', '["The exponent inside the efficiency factor, applied to the water curve across the whole of its range rather than at one point on it.", "The ratio of the fluid''s viscosity to that of water, applied at the duty point the machine is actually running at.", "The correlating parameter, which says how far from water the fluid is, applied at the best efficiency point.", "The head factor before it is equated to the flow factor, applied at the shutoff head."]'::jsonb, 2, 'Every factor on a row is read against B. The head factor is taken equal to the flow factor there, which is a simplification of the standard.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 12, 'At 320.000000 cSt the engine returns a flow factor of 0.894963166, a head factor of 0.894963166 and an efficiency factor of 0.637190119. Which of the three decides a driver?', '["The efficiency factor, so a viscous service is a power question as well as a capacity question.", "The flow factor, since the corrected flow of 1029.207641 gpm is what the driver is sized against.", "The head factor, since power follows head and the head factor is the one applied to the published curve.", "All three equally, since the corrected flow and head are the product of the factors and the power follows from both."]'::jsonb, 0, 'Correcting the flow and the head and leaving the efficiency at its water value makes the capacity look survivable while the power behind it is wrong.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 13, 'At 850.000000 cSt the engine attaches "the efficiency correction is 45.7 percent: a centrifugal pump is a poor choice for a fluid this viscous". What does it do with the row?', '["Withholds the corrected flow and head, leaving the factors and the message in their place.", "Returns it in full, with a corrected flow of 923.952933 gpm and a corrected head of 345.478053 ft.", "Returns the catalogue values unchanged, since the warning marks the branch on which no correction applies.", "Returns the row and clears the efficiency factor, since 0.456934987 is the figure the message has just disclaimed."]'::jsonb, 1, 'The warning names the efficiency correction and says what a fluid this viscous needs. The figures are still the arithmetic the method gives.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 14, 'At 9000.000000 cSt, where B is 40.385733873, the engine says "B above 40 is outside the published correlation: this service needs a positive-displacement pump or vendor viscous test data, not a corrected centrifugal curve". What is the trap on that row?', '["A caller reading only the numbers gets a refusal where the other rows carry figures, so the row looks like a bug.", "The corrected flow of 551.907863 gpm is returned at the catalogue head, so the pair no longer describes one operating point.", "B is reported above its own threshold, which means the efficiency factor of 0.074570011 was extrapolated rather than correlated.", "A caller reading only the numbers gets a corrected curve for a service the method has just disclaimed."]'::jsonb, 3, 'The warning names the parameter, names the threshold and names the two things that would answer the question. It does not withhold the numbers.'),
  ('rotating', 'intermediate', 'module', 'm05-two-pumps-and-a-water-curve', 15, 'At 1.000000 cSt the engine reports B = 0.425703013, and at 1.000001 cSt it reports 0.425703226, a difference of 2.1285145351823687e-7. What does that establish?', '["That B is a real positive number at water viscosity, on the branch where the engine then applies no correction at all.", "That B is discontinuous at water viscosity, which is why the engine switches branches there.", "That B rounds to zero at water viscosity and the engine reports the rounding rather than the value.", "That the correction is applied at 1.000001 cSt and withheld at 1.000000 cSt, which the difference in B measures."]'::jsonb, 0, 'B says how far from water the fluid is, and the decision not to correct is a separate statement carried by the note. At 1.000000 cSt that note reads "at water viscosity there is nothing to correct".'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Four quantities, all of them printed by this tier''s engines. Only one may be written down as a result. Which?', '["The required margin, because both halves of the rule behind it were measured out of the engine.", "A trimmed head, because the engine returns the ideal figure beside the real one so a reader can see the de-rating.", "NPSH available, because every term in it is arithmetic the engine defines and performs.", "A corrected flow, because the correlation behind it is checked at sixty digits by this wave''s oracle."]'::jsonb, 2, 'Measurable is not the same as sourced. The margin rule, the trim shortfall and the viscosity correction each have no publication in this repository.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'The floor of 3.000000000 ft and the fraction of 0.350000000 are quoted to nine decimal places in a course that grades nothing on them. Why bother?', '["They are the best rule available here and the one the engine applies, so a reader should know them exactly and know equally well that neither has a source.", "They will become gradeable once a publication is found, and quoting them now saves re-cutting the tier later.", "They are measurable, and a measurable figure is sourced by the measurement, which is what the nine decimals record.", "They are quoted at that precision because the required NPSH at which they change places is a recurring decimal, and a shorter quote of either half would not reproduce it."]'::jsonb, 0, 'Both halves are measurable out of the engine and the rule itself is customary. Knowing a rule exactly and knowing it is unsourced are two separate pieces of knowledge.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Two ways of moving a pump curve sit side by side in this tier. Which of them can a graded figure come from, and why?', '["The trim, because its shortfall model is stated in full and its boundaries were bisected out of the engine.", "The speed change, because the affinity laws are exact and the engine prints the subtraction that says so.", "Both, because the engine returns ideal and real columns for the trim and the ideal column is the exact law.", "Neither, because both rest on the band of speed ratios the engine reports without comment."]'::jsonb, 1, 'The speed law is not held. The shortfall model is, because the engine''s own comment calls it "the published shortfall" and names no publication.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'A change of 0.800000 is proposed and three flows appear in the working: 987.562375 gpm, 943.122068 gpm and 695.297235 gpm. Which is the flow the pump will run at?', '["987.562375 gpm, which is the flow the affinity laws give for a ratio of 0.800000.", "943.122068 gpm, which is the trimmed machine''s own flow once the shortfall has been applied to it.", "None of them, because a duty needs a required NPSH stated beside it before it can be quoted.", "695.297235 gpm, the crossing of the trimmed curve with a system that did not move."]'::jsonb, 3, '987.562375 gpm is the ideal flow of that trim and also the flow of a speed change to 0.800000. 943.122068 gpm is the real flow, and it is a point on the new curve.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'A candidate writes a margin in gpm and a viscosity in rpm. Which reading habit would have caught both?', '["Confirming the unit of every figure before writing it, since heads and margins are in feet and a viscosity is in centistokes.", "Quoting every figure to six decimals, since the engine prints pump work at that precision and a wrong unit changes the decimal count.", "Checking the figure against the published cases, since a quantity in the wrong unit will not match any of them.", "Reading the warning field first, since the engine flags a figure whose unit does not match the field it was written into."]'::jsonb, 0, 'Suction and vapour pressures are in psia, flows in gpm, power in brake horsepower, and ratios, factors and quotients are dimensionless.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The margin check refuses an available head it cannot read, and the machine combinations refuse a count that is not a whole number. What do those two refusals have in common?', '["Each is raised after the arithmetic has run, so the figures are still on the return beside the message.", "Each is a pass flag set to false, which is how this package reports an input it cannot use.", "Each is a returned object whose message names the input that defeated it, rather than a value invented over it.", "Each names the same input, since a count and an available head are both read through the finiteness test."]'::jsonb, 2, 'One needs a finite available NPSH and the other a whole number of machines. Where the engine declines, the decline is the answer.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'The tier is built on the idea that a duty point which works on paper fails in three ways. What are they?', '["On suction, on power and on the fluid.", "On change, on the fluid and on the count of machines.", "On suction, on change and on the region the duty lands in.", "On suction, on change and on the fluid."]'::jsonb, 3, 'The suction side, the affinity laws and the trim, and the fact that a catalogue curve is a water curve.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'What is true of every one of the items this course holds for the literature?', '["Each is kept out of the engine, so a reader meets it only as a named seam of the course.", "Each is used by the engine, each is printed in the course, and none of them decides a graded answer.", "Each is graded at a wider tolerance, chosen from the size of the disagreement behind it.", "Each is replaced by a default that the engine applies whenever a caller states nothing."]'::jsonb, 1, 'Holding an item means teaching it as a limit. Both halves of the margin rule are measurable and the rule is customary all the same.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Four things are absent from these engines altogether. Which absence explains why a suction margin cannot be judged without knowing the flow?', '["There is no seal calculation and no bearing calculation anywhere in the package.", "There is no compressor surge line, surge margin, recycle valve or anti-surge control.", "There is no machine curve, wheel selection, valve dynamics or rod loading.", "There is no required-NPSH-against-flow curve anywhere in the package."]'::jsonb, 3, 'The vendor curve has to be read at the duty flow before the margin means anything. A required figure read at the wrong flow is a real number off a real curve at a duty the pump is not running at.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What does this course claim to answer?', '["The duty, the power, the region the duty lands in and the margin that makes a selection acceptable, with the reasons behind each.", "The duty a vendor should be quoting against, the power and the stage count to expect, the suction margin a selection has to survive, and the reasons behind all four.", "Everything a selection package answers, since the two studios run these chains live and the engines behind them are vendored whole.", "The duty and the power only, since the suction side and the stage count both rest on held rules."]'::jsonb, 1, 'That is a smaller claim than a selection package usually makes, and every figure in the course stands behind it.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Padding the OKONO drum takes the available head from 31.040865 ft to 131.659135 ft while the vendor''s required NPSH stays at 16.000000 ft. What moves in the margin check across that sweep, and what does not?', '["The margin and the ratio move; the required margin holds at 5.600000 ft and the severity stays adequate.", "The margin, the ratio and the required margin all move, since the required margin is a fraction of what is available.", "The margin moves and the ratio holds, since the ratio is the boundary figure the rule turns on.", "The margin moves and the severity walks through all three labels, since the sweep spans a wide range of available head."]'::jsonb, 0, 'The required margin is a function of the required NPSH alone. Nothing on the sweep moved it, so every row stands against the same figure.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Two unsourced models sit in this tier, one on a change and one on a fluid. What does holding them cost?', '["Neither model can be taught, so both appear only as a named seam of the course.", "Neither model can be run, so the engine returns the catalogue values wherever one would apply.", "No trimmed flow, head or shortfall and no corrected flow, head or efficiency can be a graded answer.", "Both are graded at a wider tolerance than the rest of the course, chosen from the size of their disagreement."]'::jsonb, 2, 'The trim''s implied efficiency ratio is held with the model it falls out of, and the corrected figures with the correlation behind theirs.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 13, '16 published cases sit beside the 22 exported functions of these two modules, and on two of them the engine reads 43.590588 ft against a golden 43.573343 ft and 62.791667 ft against a golden 62.758690 ft. What do those cases establish about the engine?', '["That its answers have been checked against measured pump tests and vendor performance runs, which is what those two quotients measure.", "That its arithmetic is the arithmetic those cases describe, and no more, because every one of them was written by an oracle.", "That it is wrong on both of those cases, since a published figure is the answer and 1.000395783 and 1.000525448 are the size of the error.", "That the correlations behind them describe a real machine, which is the whole reason a package publishes its cases beside its own answers."]'::jsonb, 1, 'The goldens were written through a different route at a water density their own oracle states, so a gate against one carries a tolerance chosen from the size of that disagreement, which is 0.0005254484459904507 at its largest. There is no measured pump test, no vendor performance run and no field compressor datasheet anywhere in this course.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'A candidate cannot remember whether a required margin is graded and writes a plausible figure. What should they have done?', '["Left it, because nothing in this course is graded on a held item and a guessed figure is worse than an absent one.", "Written the figure the engine returns at the stated required NPSH, since the rule is applied whether or not it is sourced.", "Written the boundary ratio instead, since a dimensionless figure carries no unsourced units.", "Written the available head in its place, since the two are the same quantity judged against different references."]'::jsonb, 0, 'No required margin, pass flag or severity, no trimmed flow, head or shortfall, and no corrected flow, head or efficiency is ever the answer.'),
  ('rotating', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'One figure in this tier is assembled from parts and another is solved as a crossing. Which is which?', '["52.808173 ft is a crossing of the suction survey with the vendor curve; 1131.756344 gpm is assembled from scaling factors.", "Both are assembled, since the crossing is built from a fitted curve and a system curve stated through a friction head.", "Both are solved, since the suction side is solved for the head at which the liquid stops flashing.", "52.808173 ft is assembled from a pressure head, a static column and a friction; 1131.756344 gpm is a crossing."]'::jsonb, 3, 'One is a sum the engine prints on the row. The other is where two curves meet, and it moves when either of them does.'),
  ('rotating', 'intermediate', 'final', null, 1, 'On the padding sweep the row at 40.000000 psia reads 86.736058 ft of pressure head and 87.236058 ft available, and the row at 24.500000 psia reads 52.308173 ft and 52.808173 ft. What separates the two rows?', '["The drum pressure and the static column, since a padded drum carries a taller liquid level above the pump.", "The drum pressure, and nothing else, because the liquid, the gravity, the static height and the friction are held across the sweep.", "The drum pressure and the gravity, since the conversion out of pressure is done at the gravity of the liquid at that pressure.", "The drum pressure and the vapour pressure, since a liquid held at a higher pressure boils at a higher one."]'::jsonb, 1, 'A sweep whose gravity or vapour pressure drifts between rows is a set of different liquids, and the shape it draws is not the shape of padding.'),
  ('rotating', 'intermediate', 'final', null, 2, 'The OKONO survey states a source 6.000000 ft above the pump. What would change in the assembly if the source stood below it?', '["The static term would be dropped, since only a source above the pump contributes head.", "The static term would keep its sign and the friction would change its own, since the liquid is now being lifted through the line.", "The engine would refuse the survey, since a suction lift is outside what this package assembles.", "The static term would work against the suction, because its sign is a fact about the layout."]'::jsonb, 3, 'A source above the pump arrives with its height in hand and it adds. A source below it has to be lifted first.'),
  ('rotating', 'intermediate', 'final', null, 3, 'Which stated condition reaches the pressure head of 52.308173 ft and never reaches the static column of 6.000000 ft?', '["The specific gravity of 1.040000, because the conversion out of pressure runs at the gravity of the liquid being pumped.", "The suction friction of 5.500000 ft, because it is spent before the liquid reaches the flange and the pressure head is what is left.", "The drum pressure of 24.500000 psia, because a static column measured in feet is already a head and needs no conversion.", "The warning field, because a flashing liquid changes the conversion and leaves the geometry alone."]'::jsonb, 0, 'The static column is a height the liquid already has, stated in feet. The pressure head is a pressure turned into feet, and the gravity is what turns it.'),
  ('rotating', 'intermediate', 'final', null, 4, 'A suction sitting exactly at its vapour pressure, 6.200000 psia against 6.200000 psia, returns a pressure head of 0.000000 ft and an available head of 25.000000 ft. Which part of that return carries the state of the liquid?', '["The pressure head, since 0.000000 ft is the value the engine reserves for a liquid that has reached its own boiling pressure at the flange.", "The available head, since 25.000000 ft is below the figure at which a suction of this kind would normally sit.", "The warning, since the pressure head of 0.000000 ft is an ordinary arithmetic result and the available head of 25.000000 ft is positive.", "The error key, since a liquid at its vapour pressure is one of the states this call refuses to answer."]'::jsonb, 2, 'The pressure head of 0.000000 ft is an ordinary arithmetic result and there is no error key on that return, so one field and one only carries the state of the liquid.'),
  ('rotating', 'intermediate', 'final', null, 5, 'The available head of 19.143662 ft from the flashing suction is handed to the margin check against a stated required NPSH. What comes back?', '["A margin, a required margin, a ratio, a pass flag and a severity, with nothing on that return to say the liquid was already flashing.", "A refusal, since the available head arrived from a call that carried a warning and the check will not judge a warned figure.", "A severity of \"cavitating\" whatever the required head, since the pressure head behind 19.143662 ft was negative.", "A verdict with the flashing warning carried through, since the check copies any warning on its inputs into its own return."]'::jsonb, 0, 'The available head is the whole of what this function judges, and 19.143662 ft is finite and readable. A head assembled from a survey and a head somebody typed in are judged identically.'),
  ('rotating', 'intermediate', 'final', null, 6, 'The 5.500000 ft of suction friction arrives as a stated number. Which work does this package leave to another course?', '["What the required NPSH of the machine is at the duty flow.", "What the vapour pressure of the liquid is at the suction temperature.", "What the static height between the source and the pump is on the built installation.", "What a suction line''s length, bore, fittings and rate cost in feet of head."]'::jsonb, 3, 'That seam matters when a suction is marginal, because the friction is then the term most likely to have been guessed.'),
  ('rotating', 'intermediate', 'final', null, 7, 'In the crossover table, what is the column headed "the available head that exactly satisfies it"?', '["The available head a padding sweep would have to reach before the required margin column stopped holding at one figure across every row of it.", "The smallest available head the engine will judge without a warning at that required NPSH.", "The available head at which the margin is exactly the required margin, which is 16.200000 ft at a required NPSH of 12.000000 ft.", "The available head at which the floor and the fraction return the same required margin."]'::jsonb, 2, 'The boundary is where the margin equals the required margin exactly. At a required NPSH of 30.000000 ft it is 40.500000 ft.'),
  ('rotating', 'intermediate', 'final', null, 8, 'Which required NPSH in the crossover table is governed by the floor, and what does the engine apply there?', '["12.000000 ft, where the required margin is 4.200000 ft.", "4.000000 ft, where the required margin is 3.000000 ft.", "16.000000 ft, where the required margin is 5.600000 ft.", "30.000000 ft, where the required margin is 10.500000 ft."]'::jsonb, 1, 'Below the crossover of 8.571428571 ft the floor is the larger of the two halves. The other three rows in that table are governed by the fraction.'),
  ('rotating', 'intermediate', 'final', null, 9, 'Why is the figure in the last column of the crossover table called a boundary ratio rather than the rule?', '["It is a ratio while the rule is stated as a margin in feet, so the two carry different units and a reader cannot substitute one for the other.", "It is measured at the boundary of the rule while the rule itself applies across the whole range of required NPSH, so the two agree only at that point.", "It is an output of the rule at a stated required NPSH, and turning an output into a rule fails as soon as the case crosses 8.571428571 ft.", "It is derived from the floor and the fraction together, so it belongs to neither half on its own."]'::jsonb, 2, 'On the three rows the fraction governs it reads 1.350000000 every time. On the floor row it reads 1.750000000.'),
  ('rotating', 'intermediate', 'final', null, 10, 'The note on a marginal case names two things the case needs. What are they?', '["Vendor agreement and a stable suction.", "A larger pump and a stable suction.", "Vendor agreement and a re-read of the required NPSH at the duty flow.", "A padded drum and vendor agreement."]'::jsonb, 0, 'Those are the two things the engine asks for on a marginal case, and neither of them is a figure this course grades.'),
  ('rotating', 'intermediate', 'final', null, 11, 'Code that tests the error key, then the severity, then the pass flag reads three answers apart. What does code written on the pass flag alone collapse?', '["A refusal and a cavitating suction into one, leaving the marginal case correctly separate.", "A marginal suction and an adequate one into one, since both clear the vendor''s own requirement.", "A refusal and an adequate suction into one, since neither of them reports a shortfall.", "A refusal, a cavitating suction and a marginal one into a single failed check."]'::jsonb, 3, 'A refusal is a returned object carrying an error key. It is not a severity and it is not a pass of false, and the engine reported that it never ran a check.'),
  ('rotating', 'intermediate', 'final', null, 12, 'What does the margin check NOT return when it refuses?', '["A message, because the refusal names the input rather than describing it.", "A severity and a pass flag, because there is nothing left to compare the rule against.", "The required margin, because that half of the answer is computed from the required NPSH and survives the refusal.", "The ratio, because it is computed last and the other fields are returned as far as the check reached."]'::jsonb, 1, 'The whole of the return is a single error key. Nothing partial travels beside it, because there was no comparison to report on.'),
  ('rotating', 'intermediate', 'final', null, 13, 'At a speed ratio of 0.900000 the head quotient is 0.810000000 and the power quotient is 0.729000000. What would a reader miss who saw only those two columns?', '["The direction of the departure from the law, which only the difference columns carry and which a quotient column can never be read for.", "That the row was warned, which is recorded in a column the quotients do not reach.", "The size of the departure from the law, which the difference columns put at 0 and 1.1102230246251565e-16 on that row.", "That the quotients were derived rather than returned, which the difference columns are not."]'::jsonb, 2, 'A quotient column shows what happened and a difference column shows how far that is from the claim. Only the second is evidence of anything.'),
  ('rotating', 'intermediate', 'final', null, 14, 'A speed ratio of 0.800000 returns 93.717444 brake hp and a trim ratio of 0.800000 returns 93.717444 brake hp, while their flows are 987.562375 gpm and 943.122068 gpm. Why do the power figures agree?', '["The shortfall model is applied half to the flow and half to the power, and the halves cancel in the brake power.", "The power leg of a trim is left as the ideal cube, so only the head and flow legs are de-rated.", "Brake power is computed from the ideal columns of a trim, and the ideal flow at 0.800000 is 987.562375 gpm on both.", "The two changes are the same change expressed two ways, so every column of the two rows agrees."]'::jsonb, 1, 'Less flow and less head for the same power is an efficiency statement, and the return carries it as a field of its own.'),
  ('rotating', 'intermediate', 'final', null, 15, 'The implied efficiency ratio reads 1.000000000 on the trim rows at 1.000000, 0.980000 and 0.950000. Why?', '["Those three rows are inside the casing limit the trim warning names, so no efficiency change is modelled.", "The ratio is normalised to the untrimmed row, so the rows nearest it round to one.", "The power leg is the ideal cube on every row, and on shallow trims it dominates the ratio.", "The shortfall is zero there, so nothing was de-rated and there is nothing for the ratio to report."]'::jsonb, 3, 'A ratio between two legs that were not touched is one. The model leaves a trim of that depth alone.'),
  ('rotating', 'intermediate', 'final', null, 16, 'The implied efficiency ratio is 0.827200000 at a trim ratio of 0.700000, and the worked case at a trim ratio of 0.750000 reaches 0.827200000 as well. What do those two trims have in common?', '["Both sit at the cap, so both carry a shortfall percent of 12.", "Both are deeper than the vendor limit the warning names, and the model holds the ratio flat beyond it.", "Both return the same ideal flow, so the two legs of the ratio are the same on each.", "Both were measured by bisection rather than returned, so both carry the same rounding."]'::jsonb, 0, 'The shortfall is capped at 0.12, which is a head leg of 0.880000000 and a flow leg of 0.940000000 whatever the trim beyond the cap.'),
  ('rotating', 'intermediate', 'final', null, 17, 'At a trim ratio of 0.550000 the engine returns a trim percent of 44.99999999999999 and a shortfall percent of 12. What is that row for?', '["It shows the trim percent failing to reach a whole number, which is why the warning fires there.", "It shows the shortfall growing at 0.006 per further percent all the way down.", "It shows the cap holding well past the trim at which it was reached.", "It shows the deepest trim the engine will answer before it refuses."]'::jsonb, 2, 'The cap is reached at a trim ratio of 0.750000, where the trim percent is 25 and the shortfall percent is 12. It does not move after that.'),
  ('rotating', 'intermediate', 'final', null, 18, 'At a trim ratio of 0.550000 the engine describes a 45.0 percent trim. What does that message say about the vendor limit?', '["That it has been passed by more than double, so a second and deeper limit is named alongside it.", "That it usually sits near 20 percent, which is the same sentence attached at a trim ratio of 0.799900.", "That the limit moves with the depth of the cut, which is why the message restates it on each row.", "That the limit is the cap of 0.12 on the shortfall, written as a percentage of the diameter."]'::jsonb, 1, 'One sentence covers the whole range beyond the threshold, and it names efficiency falling away as what the limit is about.'),
  ('rotating', 'intermediate', 'final', null, 19, 'The extrapolation warning at a speed ratio of 100.000000 singles out one of the three legs. Which, and why does it say so rather than leave it to be inferred?', '["The power leg, because it goes as the cube and it is the figure that sizes the driver.", "The head leg, because it goes as the square and the head is what the vendor quotes a machine against.", "The flow leg, because 123445.296915 gpm is the figure that is absurd on its face.", "The power leg, because 183041883.582474 brake hp is the largest of the three figures returned."]'::jsonb, 0, 'Naming the leg is the point. A reader is told which figure the extrapolation reaches instead of being left to work it out.'),
  ('rotating', 'intermediate', 'final', null, 20, 'At a unit duty a trim ratio of 0.950000 returns a flow factor of 0.950000000. What does that tell you about the model inside those factors?', '["It has been switched off for the factor table, which is why the trim rows read as the affinity laws.", "It applies to the head factor only at that depth, which is why the flow factor is the plain ratio.", "It rounds the flow factor to the trim ratio wherever the shortfall is below a tenth of a percent.", "It leaves a trim of that depth alone, which is why the factor is the plain ratio there."]'::jsonb, 3, 'A trim ratio of 0.800000 returns 0.764000000 rather than 0.800000000, because the shortfall model is inside these factors.'),
  ('rotating', 'intermediate', 'final', null, 21, 'At a trim ratio of 0.850000 the two answers are 851.147837 gpm at 308.788996 ft and 1017.806473 gpm at 283.749561 ft. What do the heads add to what the flows already say?', '["That the two answers differ in the same direction on both coordinates, with the re-solved figures lower on each.", "That the two answers differ in opposite directions on the two coordinates, with the re-solved head the higher of the two.", "That the head gap is the shortfall and the flow gap is the system, which is how the two mechanisms separate.", "That the re-solved answer lies further down the system curve, so both of its coordinates fall."]'::jsonb, 1, 'The quotients on that row are 1.195804570 and 0.918910857. The crossing slides along a fixed system curve and the map slides along the machine''s own law.'),
  ('rotating', 'intermediate', 'final', null, 22, 'Where do the two answers for one change appear in the Pump Station Designer?', '["The crossing is printed in the card; the map is what the chart and the duty headline are both drawn from.", "Both appear in the duty headline, one above the other, so a reader can compare the two answers without opening a card.", "The crossing is the chart and the duty headline; the map is a card headed \"What a change would buy\".", "The crossing is the chart and the map is printed only when the two disagree by enough to matter."]'::jsonb, 2, 'The chart and the headline are one answer and the card is the other. Computing one and labelling it generically is what creates the confusion.'),
  ('rotating', 'intermediate', 'final', null, 23, 'The quotient columns are the one-point answer over the re-solved answer. Reading 0.949032669 at a speed ratio of 1.100000, what follows from that ordering?', '["The one-point flow of 1357.898266 gpm is below the re-solved flow of 1430.823522 gpm.", "The one-point flow is above the re-solved flow, since a quotient below one puts the denominator first.", "The two flows are within five percent of each other, which is what a quotient near one records.", "The re-solved flow is the smaller of the two on every speed row above 1.000000."]'::jsonb, 0, 'A quotient below one puts the numerator, which is the one-point answer, below the denominator.'),
  ('rotating', 'intermediate', 'final', null, 24, 'Which of the two heads printed on the 0.950000 row is the larger, and how does the quotient of 0.980245113 say so?', '["377.065419 ft is the larger, because the numerator of a quotient below one is the bigger of the two.", "Neither, because a head quotient records how far the head moved rather than which figure is above which.", "384.664421 ft is the larger, because the re-solved head is above the mapped head on every row of both tables.", "384.664421 ft is the larger, because a quotient below one puts 377.065419 ft under it."]'::jsonb, 3, 'The quotient is the one-point answer over the re-solved one. On that row the shortfall percent is 0, so the model owes nothing to either figure.'),
  ('rotating', 'intermediate', 'final', null, 25, 'The three-machine parallel row reads 1219.484579 gpm at 527.036531 ft with 406.494860 gpm per machine. What question does that last figure answer?', '["What the station delivers, which is the figure a manifold is sized on.", "What each machine is carrying, which is where it sits on its own curve.", "What a fourth machine would add, which is the difference between the rows.", "What one machine would deliver on its own, which is the reference the other columns are read against."]'::jsonb, 1, 'One machine on its own carries 1103.518695 gpm. Quoting a per-machine flow as a station flow, or the reverse, is the error the table invites.'),
  ('rotating', 'intermediate', 'final', null, 26, 'Two machines in series give 1465.998506 gpm at 734.940178 ft, with a head over one machine of 1.661125814. Which figures moved from the single-machine row, and why?', '["Both, because a taller curve crosses the same system further to the right and the system charges more head there.", "The head only, because series operation adds head at equal flow and the flow is therefore unchanged.", "The flow only, because the head over one machine is what the combination fixes and the duty head follows it.", "Neither in a way that matters, because the head over one machine is the figure the stack is judged on."]'::jsonb, 0, 'One machine gives 1103.518695 gpm at 442.434987 ft. The heads add exactly at every flow, and the crossing landed somewhere else.'),
  ('rotating', 'intermediate', 'final', null, 27, 'A station makes enough flow and cannot reach the head it needs. Which arrangement answers that shortage?', '["Parallel, because the combined curve is built by adding flows at equal head.", "Either, because both arrangements raise the duty head of the station on a friction-dominated system.", "Series, because the machines pass the same liquid one after another and their heads add.", "Neither, because the shortage is a property of the system curve and no arrangement of machines reaches it."]'::jsonb, 2, 'Parallel answers a shortage of flow at a head the station can already make. The system decides which shortage you have.'),
  ('rotating', 'intermediate', 'final', null, 28, 'At 20.000000 cSt the flow and head factors are both 0.997024668 while the efficiency factor is 0.946562979. What does that spread say?', '["The flow and head factors are equal by measurement on this row and part company further out.", "The efficiency factor carries the square of the other two, which is why it falls faster.", "The row is near enough to water that the correction has not yet taken hold on any of the three.", "The efficiency is the first of the three to move away from water, and by far the most."]'::jsonb, 3, 'At 320.000000 cSt the pair is 0.894963166 and the efficiency factor is 0.637190119. Correcting the capacity and leaving the efficiency at its water value is the mistake this invites.'),
  ('rotating', 'intermediate', 'final', null, 29, 'Three of the nine viscosity rows carry a warning and the section prints two of those messages in full. Which row''s message is not printed?', '["The 850.000000 cSt row.", "The 2400.000000 cSt row.", "The 9000.000000 cSt row.", "The 320.000000 cSt row."]'::jsonb, 1, 'The two printed are at 850.000000 cSt and at 9000.000000 cSt. The 320.000000 cSt row carries no warning at all.'),
  ('rotating', 'intermediate', 'final', null, 30, 'At 5.000000 cSt the engine reports B = 0.951900876 with the note "B at or below 1: no correction applies". What kind of statement is that note?', '["A statement about the correlating parameter being small enough that the method leaves the curve alone.", "A statement about the fluid being water, which is the other of the two branches on which no correction is applied at all.", "A statement that B could not be computed on that row, so no factors were produced.", "A statement that the correction was applied and came back at unity on all three factors."]'::jsonb, 0, 'The note at 1.000000 cSt is the other one and reads "at water viscosity there is nothing to correct". Two branches, two notes, two reasons.'),
  ('rotating', 'intermediate', 'final', null, 31, 'On the water row the corrected flow is 1150.000000 gpm against a stated best efficiency flow of 1150.000000 gpm, a difference of 0 gpm. Why are those fields present at all on a branch that corrects nothing?', '["Because a caller needs the fields to detect which branch it landed on without reading the note.", "Because the engine computes the correction on every branch and suppresses it afterwards on this one.", "Because the catalogue values unchanged are an answer, and the return shape is the same on every branch.", "Because the fields carry the stated inputs back to the caller wherever no output was produced."]'::jsonb, 2, 'They are present on the water row, on the row a millionth above it and on a corrected row. A caller does not have to know which branch it landed on to read them.'),
  ('rotating', 'intermediate', 'final', null, 32, 'A pure speed row in the factor table reads as the plain ratio and its square, and a pure trim row does not. What is the difference between the two rows made of?', '["The speed factors are read at a unit duty and the trim factors at the base duty, so the two are on different references.", "The trim factors carry the implied efficiency ratio and the speed factors do not.", "The speed factors are exact because they were measured and the trim factors are modelled, so the trim carries a rounding.", "The shortfall model sits inside the trim factors and there is nothing corresponding inside the speed factors."]'::jsonb, 3, 'A trim ratio of 0.800000 gives a flow factor of 0.764000000. A speed ratio of 0.800000 gives 0.800000000.'),
  ('rotating', 'intermediate', 'final', null, 33, 'A speed ratio of 0.700000 appears in two places with two answers, 864.117078 gpm and 502.692592 gpm. What is each of them?', '["The first is the ideal flow and the second the real flow, since a speed change is de-rated like a trim.", "The first is where the old duty point lands on the new curve; the second is where the new curve crosses the system.", "The first is the flow at the base speed scaled by the ratio and the second the same flow scaled by the ratio cubed.", "The first is a curve reading at a stated flow and the second the duty of the same machine."]'::jsonb, 1, 'Both are correct answers to two different questions. The affinity map is a real point on the new curve, and the crossing is where the machine will run.'),
  ('rotating', 'intermediate', 'final', null, 34, 'A margin check takes two numbers. On the OKONO case, where does each of them come from?', '["The available head of 52.808173 ft came from the survey; the required NPSH is a vendor figure this package does not compute.", "The available head came from the survey and the required margin of 5.600000 ft came from the vendor''s datasheet.", "Both came from the survey, since a required NPSH is one of the stated suction conditions.", "The required NPSH came from the survey and the available head is computed by the check itself."]'::jsonb, 0, 'A required figure comes off a pump test and belongs to one impeller in one casing. This package does not compute it and does not pretend to.'),
  ('rotating', 'intermediate', 'final', null, 35, 'Two held models in this tier print something beside their own answer. Which prints an ideal column beside a real one?', '["The viscosity correction, where the catalogue values are printed beside the corrected ones on every row of the table.", "The margin rule, where the required margin is printed beside the margin itself on every row of the padding sweep.", "The trim, where the affinity laws applied to a diameter ratio sit beside the de-rated figures on every row.", "Both of them, since each returns the uncorrected figure beside the corrected one."]'::jsonb, 2, 'A single de-rated answer would carry no evidence of the de-rating. On the no-correction branches of the viscosity method the corrected fields are the catalogue values themselves.'),
  ('rotating', 'intermediate', 'final', null, 36, 'The margin check and the parallel combination each refuse, and the two messages name two different inputs. What does each name?', '["One names a required NPSH that is not finite; the other names a pump curve that does not fall with flow.", "One names a machine count; the other names a curve whose crossing with a system is not a duty point.", "One names an available NPSH that is not finite; the other names a trim ratio outside the range the model covers.", "One names an available NPSH that is not finite; the other names a machine count that is not a whole number at least one."]'::jsonb, 3, 'The margin check needs a finite available NPSH. Parallel and series each need a pump curve and a whole number of machines, at least one.'),
  ('rotating', 'intermediate', 'final', null, 37, 'The trim warning names a vendor limit and the margin rule names a customary cover. Does the engine ever refuse on either?', '["Yes, the trim warning refuses beyond the cap of 0.12 and the margin rule refuses a cavitating suction.", "No. Both are reported, and neither is used to withhold an answer.", "Yes, the margin rule refuses when the severity would be cavitating, and the trim warning only comments.", "No, but the trim warning suppresses the real columns beyond the vendor limit it names."]'::jsonb, 1, 'At a trim ratio of 0.550000 the engine returns the full row with a message. A cavitating suction comes back with a severity and a pass of false.'),
  ('rotating', 'intermediate', 'final', null, 38, 'The speed table and the trim table are both anchored on 1234.452969 gpm at 417.801018 ft with 183.041884 brake hp. What is that anchoring for?', '["It is one duty on one machine, so two kinds of change are measured from the same starting point.", "It is the published duty case, so both tables can be checked against a golden.", "It is the point at which the affinity laws are defined, so neither table can begin anywhere else.", "It is the duty at which the shortfall is zero, so the trim table opens with nothing de-rated."]'::jsonb, 0, 'Both are asked there. A shared starting point is what makes the rows of the two tables readable against each other at all.'),
  ('rotating', 'intermediate', 'final', null, 39, 'At a speed ratio of 100.000000 the flow comes back as 123445.296915 gpm. Where is the extrapolation comment actually earning its keep?', '["At ratios like this one, where the figures are large enough that a reader might take them for a unit error and check.", "Inside the band, where the absence of a comment is what tells a reader the ratio was accepted as reasonable.", "Just outside the band, where the returned figures look perfectly ordinary and nothing else marks them.", "At the two ends themselves, where the behaviour changes state and the band can be walked out of the engine."]'::jsonb, 2, 'A flow of 123445.296915 gpm is absurd on its face. Suppressing a comment because the answer looked reasonable is the mistake it guards against.'),
  ('rotating', 'intermediate', 'final', null, 40, 'Of the three parts of NPSH available, which does this package compute and which is it handed?', '["It computes the pressure head and the friction; only the static height is a stated condition.", "It computes all three out of the suction survey, which is what makes each of them movable.", "It computes the static height from the survey; the pressure head and the friction are stated.", "It computes the pressure head; the static height and the suction friction are both stated conditions."]'::jsonb, 3, 'What a suction line costs in feet of head belongs to the course that owns line losses, and a height between a source and a pump is surveyed rather than derived.'),
  ('rotating', 'intermediate', 'final', null, 41, 'This tier cites another course rather than re-deriving what it owns. Which material, and where does it live?', '["The system curve and the duty point as a solved intersection, taught by the ESP course in the Production module.", "The affinity laws, the best efficiency point and the operating range, taught by the ESP course in the Production module.", "The Hydraulic Institute viscosity correction, taught by the ESP course in the Production module.", "The NPSH margin rule, taught by the ESP course in the Production module."]'::jsonb, 1, 'This course takes up the narrower question of which changes to a pump the laws describe and which they do not.'),
  ('rotating', 'intermediate', 'final', null, 42, 'A trimmed machine and a parallel stack both change the machine curve while the system stays where it is. What does the engine do in each case?', '["Scales the old duty point in the first case and solves a fresh crossing in the second.", "Solves a fresh crossing in the first case and adds the machines'' flows at the old duty head in the second.", "Solves a fresh crossing of the new curve with the old system, which is the same operation both times.", "Scales the old duty point in both cases, since the system curve did not move in either."]'::jsonb, 2, 'The combined curve is a new machine curve and the duty is solved the way any duty is solved. The affinity map is the other, separately labelled answer to a different question.');
